export type CardFigureId = keyof typeof CARD_FIGURES;

/** `id`'s card figure, with its clip id made unique by `clipId` and its text outlines in place. */
export function renderCardFigure(id: CardFigureId, clipId: string): string {
  return CARD_FIGURES[id]
    .split('__ID__')
    .join(clipId)
    .replace(/__TEXT_([A-Za-z0-9]+)__/g, (_, key: string) => {
      const text = NPC_TEXT_PATHS[key as keyof typeof NPC_TEXT_PATHS];
      if (!text) throw new Error(`card figure ${id}: no text path "${key}"`);
      return `<path d="${text.d}" fill="${text.fill}"></path>`;
    });
}
